import{_ as C,a0 as d,w as p,s as n,ao as l,I as s,x as t,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"为什么 Fedora 一开始允许使用 CC0 许可证 | LCTT x X-CMD","titleTemplate":false,"description":"为什么 Fedora 一开始允许使用 CC0 许可证 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么 Fedora 一开始允许使用 CC0 许可证 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么 Fedora 一开始允许使用 CC0 许可证 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220801 What Made Fedora Choose To Use CC0 Licensed Code As The Boot","title":"为什么 Fedora 一开始允许使用 CC0 许可证","tag":"202208","desc":""},"relativePath":"202208/20220801 What Made Fedora Choose To Use CC0 Licensed Code As The Boot.md","filePath":"[post].md"}'),i={name:"202208/20220801 What Made Fedora Choose To Use CC0 Licensed Code As The Boot.md"};function u(m,e,f,T,h,F){const o=d("Link");return p(),n("div",null,[e[15]||(e[15]=l('<h1 id="为什么-fedora-一开始允许使用-cc0-许可证" tabindex="-1">为什么 Fedora 一开始允许使用 CC0 许可证 <a class="header-anchor" href="#为什么-fedora-一开始允许使用-cc0-许可证" aria-label="Permalink to “为什么 Fedora 一开始允许使用 CC0 许可证”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/12/160739j1eqft2cpw7srssz.png" alt=""></p><p>开源是一个具有挑战性的概念。许多人认为，开源意味着可以任意的使用软件，并且可以免费下载。这实际上取决于你如何被许可 —— 开发者分享代码时使用的许可证决定了它。开源软件可以是收费的，也可以限制你如何去使用它，在极少数情况下，甚至让你陷入法律纠纷。</p><p>Fedora 项目最近决定拒绝所有使用 <ruby>知识共享<rt>Creative Commons</rt></ruby> “公共领域专用” CC0 许可证的代码，以避免这种情况的出现。CC0 将从新提交代码中准许使用的许可证列表中剔除，但是，像艺术品一类的贡献仍被允许所以它，甚至可能在个案的情况下对当前的软件包进行逐一的处理。</p><p>如果 Fedora 反对一个软件许可证，通常不会成为新闻。事实上，在那么多的许可证当中，该项目拒绝了许多许可证。这种情况的意外之处在于，CC0 最初被认为是一个有效的许可证，现在只是由于更大的自由及开源（FOSS）社区内的观点转变而被重新分类。</p><p>CC0 是因为什么让 Fedora 决定停止支持它，这又是否意味着你不能在你自己的项目中使用它呢？</p><p>这一段描述让最熟悉知识共享及其许可系列的人惊讶的是，Fedora 最初批准了 CC0 的软件。毕竟，知识共享从一开始的目标是为艺术作品提供一系列明确的许可证。该组织的使命和许可证的要求在其名称“知识共享”中就有所体现。</p><p>为了“克服分享信息和创造力的法律障碍”，提供一个自由的框架来为人们组织分享如音乐、医学或教育材料的资源，知识共享组织的前身——<ruby>开放内容项目<rt>Open Content Project</rt></ruby>，于 2001 年成立。然而，软件从来不是它的组成要素。为什么呢？因为那时，如 MIT、GPL 一类的重要的软件许可证已经出现了十几年。</p><p>很明显，如果一家公司不遗余力地警告你他们制造的东西不适合某种特定用途，你也许应该相信他们。知识共享的 FAQ 列出了一些反对在软件上使用他们的许可证的令人信服的论据，但对于像 Fedora 项目这样的用户来说，其中一个问题特别突出：专利权。</p><p>鉴于 CC0 许可证是为公共领域的作品准备的，而且通过使用它，创作者明确地“放弃了他或她在版权法下对作品的所有权利”，这似乎矛盾的。但是，问题在于，版权法并不适用于专利。事实上，仔细审视许可证的完整措辞后可以发现，它在一个令人担忧的部分解决了这个问题，该部分内容如下：“宣告者拥有的任何商标或专利权都没有被本文本放弃、抛弃、交出、租赁或以其他方式修改。”</p><p>换言之，即使被 CC0 许可的东西的作者可能愿意放弃对它的权力，但他们仍然可以自由的为它申请专利。更糟糕的是，他们仍然保留着以他们认为合适的方式使用该专利的能力。</p><p>理论上来说，这意味着最初在 CC0 下提供的源代码的人在发布了代码之后，他们可能会在之后断言任何使用该代码的人侵犯了他们的专利，并要求支付专利费。</p><p>这显然会让像 Fedora 这样的项目担忧。考虑一下这样的情形：CC0 许可的代码进入到一个系统的核心，然后被提供给数以百万计的用户。突然间，不知道从哪里冒出来的原创作者，声称侵犯了专利权，并要求付款。红帽或 Fedora 的律师可以驳倒这种说法么？也许吧。那么，为了查明真相而使用 CC0 代码值得么？不值得。</p><p>要着重提到的是，这完全不是一个新问题。实际上，早在 2012 年，专利条款就阻止了开源倡议（OSI）许可证的审查委员会，他们无法最终确定 CC0 是否真正符合他们对开源许可证的定义。委员会未能达成一致意见，因为其成员认为将此类条款纳入软件许可将创造一个危险的先例。考虑到 Fedora 动荡的历史，它最初接受 CC0 的决定着实让人费解。</p><hr>',15)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/08/what-made-fedora-choose-to-use-cc0-licensed-code-as-the-boot/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/08/what-made-fedora-choose-to-use-cc0-licensed-code-as-the-boot/",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=t("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:a(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 选题：",-1)),r(o,{href:"https://github.com/lkxed"},{default:a(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 译者：",-1)),r(o,{href:"https://github.com/yjacks"},{default:a(()=>[...e[4]||(e[4]=[t("yjacks",-1)])]),_:1}),e[9]||(e[9]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:a(()=>[...e[11]||(e[11]=[t("Linux中国",-1)])]),_:1}),e[14]||(e[14]=t(" 荣誉推出",-1))])])}const b=C(i,[["render",u]]);export{L as __pageData,b as default};
